// ESP32 — Buzzer Melodie
// "Alle meine Entchen" — die ersten 8 Noten

#define BUZZER_PIN 25
#define KANAL 0

// Wie hoch jede Note klingen soll (Hertz)
int frequenzen[] = {262, 294, 330, 349, 392, 392, 440, 440};

// Wie lange jede Note dauern soll (Millisekunden)
int dauern[] = {400, 400, 400, 400, 800, 800, 400, 400};

int anzahlNoten = 8;

void setup() {
  ledcSetup(KANAL, 1000, 8);
  ledcAttachPin(BUZZER_PIN, KANAL);
}

void loop() {
  for (int i = 0; i < anzahlNoten; i++) {
    ledcWriteTone(KANAL, frequenzen[i]);
    delay(dauern[i]);
    ledcWriteTone(KANAL, 0);  // kurze Pause zwischen Noten
    delay(50);
  }
  delay(2000);  // dann ein bisschen warten und wieder von vorne
}
